CREATE OR REPLACE PROCEDURE oracle_charge_programs_cdc_merge_261113_cbb7()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS
$$
BEGIN
    BEGIN TRANSACTION;

    MERGE INTO SF_BIGHAMMER.SILVER.DIM_ORACLE_PROGRAMS AS target
    USING (
    WITH RAW_ORACLE_CHARGE_PROGRAM_CDC AS (
        SELECT PROGRAM_ID AS PROGRAM_ID_src_1, COMPANY_ID AS COMPANY_ID_src_1, PROGRAM_NAME AS PROGRAM_NAME_src_1, PROGRAM_DESCRIPTION AS PROGRAM_DESCRIPTION_src_1, TRANSACTION_TYPE AS TRANSACTION_TYPE_src_1, FREQUENCY AS FREQUENCY_src_1, DOC_TYPE AS DOC_TYPE_src_1, EXACT_AMOUNT AS EXACT_AMOUNT_src_1, SCHEDULE_VALIDATION AS SCHEDULE_VALIDATION_src_1, CREATED_DATE AS CREATED_DATE_src_1, CREATED_BY AS CREATED_BY_src_1, MODIFIED_DATE AS MODIFIED_DATE_src_1, MODIFIED_BY AS MODIFIED_BY_src_1, CDC_OPERATION AS CDC_OPERATION_src_1 FROM SF_BIGHAMMER.RAW.RAW_ORACLE_CHARGE_PROGRAM_CDC
    ),
    RAW_ZENITH_CRM_PORTALCLIENTLOG AS (
        SELECT ID AS ID_src_2, CLIENTID AS CLIENTID_src_2, LOGTYPEID AS LOGTYPEID_src_2, IPADDRESS AS IPADDRESS_src_2, USERAGENT AS USERAGENT_src_2, EXTRA AS EXTRA_src_2, LOGDATE AS LOGDATE_src_2, TOKEN AS TOKEN_src_2, ENCRYPTAUTOLOGINMESSAGE AS ENCRYPTAUTOLOGINMESSAGE_src_2, AESKEY AS AESKEY_src_2, AESIV AS AESIV_src_2, LOAD_TIMESTAMP AS LOAD_TIMESTAMP_src_2, SOURCE_BLOB_FILE_NAME AS SOURCE_BLOB_FILE_NAME_src_2, CDC_OPERATION AS CDC_OPERATION_src_2 FROM SF_BIGHAMMER.RAW.RAW_ZENITH_CRM_PORTALCLIENTLOG
    ),
    RAW_ORACLE_TRANSACTION_RULES_CDC AS (
        SELECT TRANSACTION_RULE_ID AS TRANSACTION_RULE_ID_src_3, TRANSACTION_CLASS AS TRANSACTION_CLASS_src_3, TRANSACTION_TYPE AS TRANSACTION_TYPE_src_3, POLICY_GROUP_ID AS POLICY_GROUP_ID_src_3, DESCRIPTION AS DESCRIPTION_src_3, ACTIVE_FLAG AS ACTIVE_FLAG_src_3, COMPANY_ID AS COMPANY_ID_src_3, PAID_BY AS PAID_BY_src_3, FEE_AMOUNT AS FEE_AMOUNT_src_3, FROM_ACCOUNT_ID AS FROM_ACCOUNT_ID_src_3, TO_ACCOUNT_ID AS TO_ACCOUNT_ID_src_3, MEMO AS MEMO_src_3, QUEUE_SCHED AS QUEUE_SCHED_src_3, POST_SCHED AS POST_SCHED_src_3, CREATION_DATE AS CREATION_DATE_src_3, MODIFIED_DATE AS MODIFIED_DATE_src_3, MODIFIED_BY AS MODIFIED_BY_src_3, CDC_OPERATION AS CDC_OPERATION_src_3 FROM SF_BIGHAMMER.RAW.RAW_ORACLE_TRANSACTION_RULES_CDC
    ),
    filter_cdc_operation AS (
        SELECT * FROM RAW_ORACLE_CHARGE_PROGRAM_CDC WHERE CDC_OPERATION_src_1 IN ('I', 'U')
    ),
    join_portal_client_log AS (
        SELECT * FROM filter_cdc_operation left JOIN RAW_ZENITH_CRM_PORTALCLIENTLOG ON filter_cdc_operation.COMPANY_ID_src_1 = RAW_ZENITH_CRM_PORTALCLIENTLOG.CLIENTID_src_2
    ),
    DIM_ORACLE_PROGRAMS_rename AS (
        SELECT PROGRAM_ID_src_1 AS PROGRAM_ID, COMPANY_ID_src_1 AS COMPANY_ID, PROGRAM_NAME_src_1 AS PROGRAM_NAME, PROGRAM_DESCRIPTION_src_1 AS PROGRAM_DESCRIPTION, TRANSACTION_TYPE_src_1 AS TRANSACTION_TYPE_CODE, FREQUENCY_src_1 AS FREQUENCY, DOC_TYPE_src_1 AS DOC_TYPE_CODE, EXACT_AMOUNT_src_1 AS EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_src_1 AS SCHEDULE_VALIDATION_FLAG, PROGRAM_ID_src_1 AS SOURCE_SYSTEM_ID, CREATED_DATE_src_1 AS SRC_CREATED_AT, MODIFIED_DATE_src_1 AS SRC_MODIFIED_AT, CREATED_BY_src_1 AS SRC_CREATED_BY, MODIFIED_BY_src_1 AS SRC_MODIFIED_BY, CURRENT_TIMESTAMP() AS CREATED_AT, CURRENT_TIMESTAMP() AS MODIFIED_AT FROM join_portal_client_log
    ),
    DIM_ORACLE_PROGRAMS_final AS (
        SELECT PROGRAM_ID, COMPANY_ID, PROGRAM_NAME, PROGRAM_DESCRIPTION, TRANSACTION_TYPE_CODE, FREQUENCY, DOC_TYPE_CODE, EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID, SRC_CREATED_AT, SRC_MODIFIED_AT, SRC_CREATED_BY, SRC_MODIFIED_BY, CREATED_AT, MODIFIED_AT, CASE WHEN FREQUENCY = 'M' THEN 'Monthly' WHEN FREQUENCY = 'Q' THEN 'Quarterly' WHEN FREQUENCY = 'Y' THEN 'Yearly' ELSE NULL END AS FREQUENCY_DESCRIPTION, 'SYSTEM' AS SYSTEM_DESCRIPTION FROM DIM_ORACLE_PROGRAMS_rename
    )
    SELECT PROGRAM_ID, COMPANY_ID, PROGRAM_NAME, PROGRAM_DESCRIPTION, TRANSACTION_TYPE_CODE, FREQUENCY, DOC_TYPE_CODE, EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID, SRC_CREATED_AT, SRC_MODIFIED_AT, SRC_CREATED_BY, SRC_MODIFIED_BY, CREATED_AT, MODIFIED_AT, FREQUENCY_DESCRIPTION FROM DIM_ORACLE_PROGRAMS_final
    ) AS source
    ON target.PROGRAM_ID = source.PROGRAM_ID
    WHEN MATCHED THEN UPDATE SET target.COMPANY_ID = source.COMPANY_ID, target.PROGRAM_NAME = source.PROGRAM_NAME, target.PROGRAM_DESCRIPTION = source.PROGRAM_DESCRIPTION, target.TRANSACTION_TYPE_CODE = source.TRANSACTION_TYPE_CODE, target.FREQUENCY = source.FREQUENCY, target.DOC_TYPE_CODE = source.DOC_TYPE_CODE, target.EXACT_AMOUNT_FLAG = source.EXACT_AMOUNT_FLAG, target.SCHEDULE_VALIDATION_FLAG = source.SCHEDULE_VALIDATION_FLAG, target.SOURCE_SYSTEM_ID = source.SOURCE_SYSTEM_ID, target.SRC_CREATED_AT = source.SRC_CREATED_AT, target.SRC_MODIFIED_AT = source.SRC_MODIFIED_AT, target.SRC_CREATED_BY = source.SRC_CREATED_BY, target.SRC_MODIFIED_BY = source.SRC_MODIFIED_BY, target.MODIFIED_AT = source.MODIFIED_AT, target.FREQUENCY_DESCRIPTION = source.FREQUENCY_DESCRIPTION
    WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, COMPANY_ID, PROGRAM_NAME, PROGRAM_DESCRIPTION, TRANSACTION_TYPE_CODE, FREQUENCY, DOC_TYPE_CODE, EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID, SRC_CREATED_AT, SRC_MODIFIED_AT, SRC_CREATED_BY, SRC_MODIFIED_BY, CREATED_AT, MODIFIED_AT, FREQUENCY_DESCRIPTION) VALUES (source.PROGRAM_ID, source.COMPANY_ID, source.PROGRAM_NAME, source.PROGRAM_DESCRIPTION, source.TRANSACTION_TYPE_CODE, source.FREQUENCY, source.DOC_TYPE_CODE, source.EXACT_AMOUNT_FLAG, source.SCHEDULE_VALIDATION_FLAG, source.SOURCE_SYSTEM_ID, source.SRC_CREATED_AT, source.SRC_MODIFIED_AT, source.SRC_CREATED_BY, source.SRC_MODIFIED_BY, source.CREATED_AT, source.MODIFIED_AT, source.FREQUENCY_DESCRIPTION);

    COMMIT;

    RETURN 'Success';
EXCEPTION
  WHEN OTHER THEN
    ROLLBACK;
    RAISE;
END
$$;